import { odinUrl, odinReferences } from '../utils/paths.js';
import { fetch, getFragmentId, getRequestInfos } from '../utils/common.js';
import { logDebug } from '../utils/log.js';

const SETTINGS_ID_PATH = 'settings/index';
const COLLECTION_MODEL_ID = 'L2NvbmYvbWFzL3NldHRpbmdzL2RhbS9jZm0vbW9kZWxzL2NvbGxlY3Rpb24';
const CONFIG_CACHE_TTL = 5 * 60 * 1000;

/**
 * Available setting name definitions.
 */
export const SETTING_NAME_DEFINITIONS = [
    { name: 'addon', valueType: 'optional-text', editor: 'addon' },
    { name: 'secureLabel', valueType: 'optional-text', editor: 'text', propertyName: 'showSecureLabel' },
    { name: 'displayAnnual', valueType: 'boolean' },
    { name: 'displayPlanType', valueType: 'boolean', propertyName: 'showPlanType' },
    { name: 'quantitySelect', valueType: 'optional-text', editor: 'quantity-select' },
];

export const SETTING_NAME_BY_VALUE = new Map(SETTING_NAME_DEFINITIONS.map((definition) => [definition.name, definition]));

let settingsCache;

export function clearSettingsCache(preview = false) {
    if (preview) {
        console.log('Clearing settings preview cache');
        Object.keys(localStorage).forEach((key) => {
            if (key.startsWith('settings-')) {
                localStorage.removeItem(key);
            }
        });
    } else {
        settingsCache = undefined;
    }
}

async function cacheKey(context) {
    const { surface } = await getRequestInfos(context);
    return `settings-${surface}`;
}

async function getCachedSettings(context) {
    const key = await cacheKey(context);
    const cacheEntry = context.preview ? JSON.parse(localStorage.getItem(key)) : settingsCache?.[key];
    if (cacheEntry) {
        cacheEntry.isExpired = Date.now() - cacheEntry.timestamp > CONFIG_CACHE_TTL;
        return cacheEntry;
    }
    return null;
}

async function cache(context, settings) {
    const key = await cacheKey(context);
    const cacheEntry = {
        settings,
        timestamp: Date.now(),
    };
    if (context.preview) {
        localStorage.setItem(key, JSON.stringify(cacheEntry));
    } else {
        settingsCache = settingsCache || {};
        settingsCache[key] = cacheEntry;
    }
    return settings;
}

async function getSettingsId(context) {
    const { surface } = await getRequestInfos(context);
    const { preview } = context;
    const settingsUrl = odinUrl(surface, { fragmentPath: SETTINGS_ID_PATH, preview });
    const { id, status, message } = await getFragmentId(context, settingsUrl, 'settings-id');
    if (status != 200) {
        return { status, message };
    }
    return { status: 200, id };
}

function normalizeBoolean(value) {
    if (value === true || value === 'true') return true;
    if (value === false || value === 'false') return false;
    return value;
}

function extractValue(entry, fragment) {
    const definition = SETTING_NAME_BY_VALUE.get(entry.name);
    const propertyName = definition?.propertyName || entry.name;
    const localeValue = fragment.fields?.[propertyName];
    let booleanValue = normalizeBoolean(entry.booleanValue);
    let textValue = entry.textValue;
    if (typeof localeValue !== 'undefined') {
        if (['boolean', 'optional-text'].includes(entry.valuetype)) {
            booleanValue = normalizeBoolean(localeValue);
        }
        if (entry.valuetype === 'optional-text' && normalizeBoolean(localeValue) === false) {
            textValue = '';
        }
        if (entry.valuetype === 'text') {
            textValue = localeValue;
        }
    }
    switch (entry.valuetype) {
        case 'boolean':
            return booleanValue;
        case 'richText':
            return entry.richTextValue;
        case 'text':
            return textValue;
        case 'optional-text':
            return booleanValue ? textValue : '';
        default:
            return booleanValue;
    }
}

export function collectSettingEntries(settingFragment) {
    const { references } = settingFragment;
    const grouped = {};

    for (const ref of Object.values(references ?? {})) {
        const {
            value: { fields },
        } = ref;
        if (!fields) continue;
        const { name, locales, tags } = fields;
        if (!name) continue;
        if (!grouped[name]) {
            grouped[name] = { default: null, override: [] };
        }
        if (locales?.length > 0 || tags?.length > 0) {
            grouped[name].override.push(fields);
        } else {
            grouped[name].default = fields;
        }
    }

    return grouped;
}

export async function getSettings(context) {
    /* c8 ignore next 1 */
    if (context.hasExternalSettings) return context.settings;
    const cachedSettings = await getCachedSettings(context);
    if (cachedSettings && !cachedSettings.isExpired) return cachedSettings.settings;
    const { id } = await getSettingsId(context);
    if (!id) {
        return null;
    }
    const response = await fetch(odinReferences(id, true, context.preview), context, 'settings');

    if (response.status !== 200) {
        logDebug(() => 'Failed to fetch settings fragment', context);
        return null;
    }

    const settings = collectSettingEntries(response.body);
    return await cache(context, settings);
}

async function init(initContext) {
    return await getSettings(initContext);
}

function resolveSettingEntry(fragment, locale, setting) {
    const defaultEntry = setting.default;
    const template = fragment.fields?.variant;
    if (!defaultEntry) return null;
    if (defaultEntry.templates?.length > 0 && !defaultEntry.templates.includes(template)) return null;
    const filteredLocale = setting.override.filter(
        (overrideSetting) =>
            !overrideSetting.locales || overrideSetting.locales.length === 0 || overrideSetting.locales.includes(locale),
    );
    if (filteredLocale.length == 0) return defaultEntry;
    // Find all overrides matching the locale; now select best by tags
    let bestMatch = defaultEntry;
    let maxTagMatches = -1;
    const tags = fragment.fields?.tags;
    if (filteredLocale.length > 1 && tags?.length > 0) {
        for (const overrideSetting of filteredLocale) {
            const tagMatches = overrideSetting.tags.filter((tag) => tags.includes(tag)).length;
            if (tagMatches > maxTagMatches) {
                maxTagMatches = tagMatches;
                bestMatch = overrideSetting;
            }
        }
    } else if (filteredLocale.length === 1) {
        // No tags or no fragment tags; just return the first matching override
        bestMatch = filteredLocale[0];
    }

    return { ...defaultEntry, ...bestMatch };
}

function applySettings(context, fragment, locale, settings) {
    for (const key of Object.keys(settings)) {
        const entry = resolveSettingEntry(fragment, locale, settings[key]);
        if (!entry) continue;
        fragment.settings = {
            ...fragment.settings,
            [entry.name]: extractValue(entry, fragment),
        };
    }
    //temporary fix waiting for MWPW-189860 to be implemented
    if (fragment?.fields?.perUnitLabel) {
        fragment.priceLiterals ??= {};
        fragment.priceLiterals.perUnitLabel = fragment.fields.perUnitLabel;
    }
    logDebug(() => `Applying settings for fragment ${fragment.id}: ${JSON.stringify(fragment.settings)}`, context);
}

function applyCollectionSettings(context, locale, settings) {
    if (context.body?.references) {
        Object.entries(context.body.references).forEach(([key, ref]) => {
            if (ref && ref.type === 'content-fragment') {
                applySettings(context, ref.value, locale, settings);
            }
        });
    }

    context.body.placeholders = {
        searchText: '{{coll-search-text}}',
        filtersText: '{{coll-filters-text}}',
        sortText: '{{coll-sort-text}}',
        popularityText: '{{coll-popularity-text}}',
        alphabeticallyText: '{{coll-alphabetically-text}}',
        noResultsText: '{{coll-no-results-text}}',
        plansSidenavTitle: '{{coll-plans-sidenav-title}}',
        catalogSidenavTitle: '{{coll-catalog-sidenav-title}}',
        catalogSpecialOffersAlt: '{{catalog-special-offers-alt}}',
        sidenavFilterCategories: '{{sidenav-filter-categories}}',
        sidenavResources: '{{sidenav-resources}}',
        resultText: '{{coll-result-text}}',
        resultsText: '{{coll-results-text}}',
        resultMobileText: '{{coll-result-mobile-text}}',
        resultsMobileText: '{{coll-results-mobile-text}}',
        searchResultText: '{{coll-search-result-text}}',
        searchResultsText: '{{coll-search-results-text}}',
        searchResultMobileText: '{{coll-search-result-mobile-text}}',
        searchResultsMobileText: '{{coll-search-results-mobile-text}}',
        noSearchResultsText: '{{coll-no-search-results-text}}',
        noSearchResultsMobileText: '{{coll-no-search-results-mobile-text}}',
        showMoreText: '{{coll-show-more-text}}',
    };

    context.dictionary = {
        ...context?.dictionary,
        'coll-filter': '<span data-placeholder=\\"filter\\"></span>',
        'coll-result-count': '<span data-placeholder=\\"resultCount\\"></span>',
        'coll-search-term': '<span data-placeholder=\\"searchTerm\\"></span>',
    };

    context.body.settings = context.body.settings || {};
    context.body.settings.tagLabels =
        Object.fromEntries(['desktop', 'mobile', 'web'].map((label) => [label, `{{coll-tag-filter-${label}}}`])) || {};
}

function applyPriceLiterals(fragment) {
    if (fragment) {
        fragment.priceLiterals = {
            recurrenceLabel: '{{price-literal-recurrence-label}}',
            recurrenceAriaLabel: '{{price-literal-recurrence-aria-label}}',
            perUnitLabel: '{{price-literal-per-unit-label}}',
            perUnitAriaLabel: '{{price-literal-per-unit-aria-label}}',
            freeLabel: '{{price-literal-free-label}}',
            freeAriaLabel: '{{price-literal-free-aria-label}}',
            taxExclusiveLabel: '{{price-literal-tax-exclusive-label}}',
            taxInclusiveLabel: '{{price-literal-tax-inclusive-label}}',
            alternativePriceAriaLabel: '{{price-literal-alternative-price-aria-label}}',
            strikethroughAriaLabel: '{{price-literal-strikethrough-aria-label}}',
            planTypeLabel: '{{price-literal-plan-type-label}}',
        };
    }
}

async function settings(context) {
    applyPriceLiterals(context.body);

    const settings = await context.promises?.settings;

    logDebug(() => `Settings transformer: fetched settings ${JSON.stringify(settings)}`, context);

    const { body, locale } = context;

    if (settings) {
        if (body?.model?.id === COLLECTION_MODEL_ID) {
            applyCollectionSettings(context, locale, settings);
        } else {
            applySettings(context, body, locale, settings);
        }
    }

    return context;
}

export const transformer = {
    name: 'settings',
    init,
    process: settings,
};
export { applyCollectionSettings };

import { createQuantitySelectValue } from '../common/fields/quantity-select.js';
import { SETTING_NAME_BY_VALUE } from '../../../io/www/src/fragment/transformers/settings.js';

/**
 * Returns the setting definition by name.
 * @param {string} name
 * @returns {{ name: string, valueType: string, editor: string } | undefined}
 */
export const getSettingNameDefinition = (name) => SETTING_NAME_BY_VALUE.get(name);

/**
 * Returns deterministic default value for a setting name definition.
 * @param {{ editor: string }} definition
 * @returns {string | boolean}
 */
export const getSettingDefaultValue = (definition) => {
    if (definition.editor === 'boolean') return true;
    if (definition.editor === 'quantity-select') {
        return createQuantitySelectValue({ title: '', min: '1', step: '1' });
    }
    return '';
};

import { SELECTOR_MAS_INLINE_PRICE } from './constants.js';
import { UptLink } from './upt-link.js';
import { createTag } from './utils.js';

const DEFAULT_BADGE_COLOR = '#000000';
const DEFAULT_BADGE_BACKGROUND_COLOR = '#F8D904';
const DEFAULT_BORDER_COLOR = '#EAEAEA';
const DEFAULT_TRIAL_BADGE_BORDER_COLOR = '#31A547';
const CHECKOUT_STYLE_PATTERN = /(accent|primary|secondary)(-(outline|link))?/;
export const ANALYTICS_TAG = 'mas:product_code/';
export const ANALYTICS_LINK_ATTR = 'daa-ll';
export const ANALYTICS_SECTION_ATTR = 'daa-lh';
const SPECTRUM_BUTTON_SIZES = ['XL', 'L', 'M', 'S'];
const TEXT_TRUNCATE_SUFFIX = '...';

/**
 * Normalizes variant names for consistency.
 * Converts any variant starting with 'plans' to just 'plans'.
 * @param {string} variant - The variant name to normalize
 * @returns {string} The normalized variant name
 */
export function normalizeVariant(variant) {
    if (!variant) return variant;
    if (variant.startsWith('plans')) return 'plans';
    return variant;
}

export function appendSlot(fieldName, fields, el, mapping) {
    const config = mapping[fieldName];
    if (fields[fieldName] && config) {
        const attributes = { slot: config?.slot, ...config?.attributes };
        let content = fields[fieldName];

        // Handle maxCount if specified in the config
        if (config.maxCount && typeof content === 'string') {
            const [truncatedContent, cleanContent] = getTruncatedTextData(
                content,
                config.maxCount,
                config.withSuffix,
            );
            if (truncatedContent !== content) {
                attributes.title = cleanContent; // Add full text as title attribute for tooltip
                content = truncatedContent;
            }
        }

        const tag = createTag(config.tag, attributes, content);
        el.append(tag);
    }
}

export function processMnemonics(fields, merchCard, mnemonicsConfig) {
    // Filter out empty string sentinel values (indicates explicitly cleared)
    const icons = (fields.mnemonicIcon || []).filter((icon) => icon);

    const mnemonics = icons.map((icon, index) => ({
        icon,
        alt: fields.mnemonicAlt?.[index] ?? '',
        link: fields.mnemonicLink?.[index] ?? '',
    }));

    mnemonics?.forEach(({ icon: src, alt, link: href }) => {
        if (href && !/^https?:/.test(href)) {
            try {
                href = new URL(`https://${href}`).href.toString();
            } catch (e) {
                /* c8 ignore next 2 */
                href = '#';
            }
        }

        const attrs = {
            slot: 'icons',
            src,
            loading: merchCard.loading,
            size: mnemonicsConfig?.size ?? 'l',
        };
        if (alt) attrs.alt = alt;
        if (href) attrs.href = href;
        const merchIcon = createTag('merch-icon', attrs);
        merchCard.append(merchIcon);
    });

    const slotIcons = merchCard.shadowRoot.querySelector('slot[name="icons"]');
    if (slotIcons) {
        slotIcons.style.display = mnemonics?.length ? null : 'none';
    }
}

function processBadge(fields, merchCard, mapping) {
    if (mapping.badge?.slot) {
        if (fields.badge?.length && !fields.badge?.startsWith('<merch-badge')) {
            let badgeDefaultBgColor = DEFAULT_BADGE_BACKGROUND_COLOR;
            let setBorderColorForBadge = false;

            if (mapping.allowedBadgeColors?.includes(mapping.badge?.default)) {
                badgeDefaultBgColor = mapping.badge?.default;
                if (!fields.borderColor) {
                    setBorderColorForBadge = true;
                }
            }

            const bgColorToUse =
                fields.badgeBackgroundColor || badgeDefaultBgColor;
            let borderColorToUse = fields.borderColor || '';
            if (setBorderColorForBadge) {
                borderColorToUse = mapping.badge?.default;
                fields.borderColor = mapping.badge?.default;
            }

            fields.badge = `<merch-badge variant="${fields.variant}" background-color="${bgColorToUse}" border-color="${borderColorToUse}">${fields.badge}</merch-badge>`;
        }
        appendSlot('badge', fields, merchCard, mapping);
    } else {
        if (fields.badge) {
            merchCard.setAttribute('badge-text', fields.badge);

            // Only set badge-color if not disabled
            if (!mapping.disabledAttributes?.includes('badgeColor')) {
                merchCard.setAttribute(
                    'badge-color',
                    fields.badgeColor || DEFAULT_BADGE_COLOR,
                );
            }

            // Only set badge-background-color if not disabled
            if (!mapping.disabledAttributes?.includes('badgeBackgroundColor')) {
                merchCard.setAttribute(
                    'badge-background-color',
                    fields.badgeBackgroundColor ||
                        DEFAULT_BADGE_BACKGROUND_COLOR,
                );
            }

            merchCard.setAttribute(
                'border-color',
                fields.badgeBackgroundColor || DEFAULT_BADGE_BACKGROUND_COLOR,
            );
        } else {
            merchCard.setAttribute(
                'border-color',
                fields.borderColor || DEFAULT_BORDER_COLOR,
            );
        }
    }
}

export function processTrialBadge(fields, merchCard, mapping) {
    if (mapping.trialBadge && fields.trialBadge) {
        if (!fields.trialBadge.startsWith('<merch-badge')) {
            // Only use trialBadgeBorderColor if not disabled
            const borderColorToUse =
                (!mapping.disabledAttributes?.includes(
                    'trialBadgeBorderColor',
                ) &&
                    fields.trialBadgeBorderColor) ||
                DEFAULT_TRIAL_BADGE_BORDER_COLOR;
            fields.trialBadge = `<merch-badge variant="${fields.variant}" border-color="${borderColorToUse}">${fields.trialBadge}</merch-badge>`;
        }
        appendSlot('trialBadge', fields, merchCard, mapping);
    }
}

export function processSize(fields, merchCard, sizeConfig) {
    if (sizeConfig?.includes(fields.size)) {
        merchCard.setAttribute('size', fields.size);
    }
}

export function processCardName(fields, merchCard) {
    if (fields.cardName) {
        merchCard.setAttribute('name', fields.cardName);
    }
}

export function processTitle(fields, merchCard, titleConfig) {
    if (fields.cardTitle) {
        fields.cardTitle = processMnemonicElements(fields.cardTitle);
    }
    appendSlot('cardTitle', fields, merchCard, { cardTitle: titleConfig });
}

export function processSubtitle(fields, merchCard, mapping) {
    appendSlot('subtitle', fields, merchCard, mapping);
}

export function processBackgroundColor(
    fields,
    merchCard,
    allowedColors,
    backgroundColorConfig,
) {
    if (
        !fields.backgroundColor ||
        fields.backgroundColor.toLowerCase() === 'default'
    ) {
        merchCard.style.removeProperty('--merch-card-custom-background-color');
        merchCard.removeAttribute('background-color');
        return;
    }

    if (allowedColors?.[fields.backgroundColor]) {
        merchCard.style.setProperty(
            '--merch-card-custom-background-color',
            `var(${allowedColors[fields.backgroundColor]})`,
        );
        merchCard.setAttribute('background-color', fields.backgroundColor);
    } else if (backgroundColorConfig?.attribute && fields.backgroundColor) {
        merchCard.setAttribute(
            backgroundColorConfig.attribute,
            fields.backgroundColor,
        );
        merchCard.style.removeProperty('--merch-card-custom-background-color');
    }
}

export function processBorderColor(fields, merchCard, variantMapping) {
    const borderColorConfig = variantMapping?.borderColor;
    const customBorderColor = '--consonant-merch-card-border-color';

    if (fields.borderColor?.toLowerCase() === 'transparent') {
        merchCard.style.setProperty(customBorderColor, 'transparent');
    } else if (fields.borderColor && borderColorConfig) {
        // Check if it's a gradient using specialValues or pattern matching
        const specialValue =
            borderColorConfig?.specialValues?.[fields.borderColor];
        const isGradient =
            specialValue?.includes('gradient') ||
            /-gradient/.test(fields.borderColor);
        // Check if it's a spectrum color that needs attribute-based styling
        const isSpectrumColor = /^spectrum-.*-(plans|special-offers)$/.test(
            fields.borderColor,
        );

        if (isGradient) {
            // For gradients, set both attributes needed for CSS selectors
            merchCard.setAttribute('gradient-border', 'true');

            // Find the key name for this gradient value
            let borderColorKey = fields.borderColor;
            if (borderColorConfig?.specialValues) {
                // Reverse lookup: find which key maps to this value
                for (const [key, value] of Object.entries(
                    borderColorConfig.specialValues,
                )) {
                    if (value === fields.borderColor) {
                        borderColorKey = key;
                        break;
                    }
                }
            }

            merchCard.setAttribute('border-color', borderColorKey);
            merchCard.style.removeProperty(customBorderColor);
        } else if (isSpectrumColor) {
            // For spectrum colors (like spectrum-red-700-plans), set both attribute and CSS variable
            // Attribute enables CSS selectors like :host([border-color='spectrum-red-700-plans']) for drop-shadow
            // CSS variable is still needed for border color rendering
            merchCard.setAttribute('border-color', fields.borderColor);
            merchCard.style.setProperty(
                customBorderColor,
                `var(--${fields.borderColor})`,
            );
        } else {
            // For regular colors, use CSS variable
            merchCard.style.setProperty(
                customBorderColor,
                `var(--${fields.borderColor})`,
            );
        }
    }
}

export function processBackgroundImage(
    fields,
    merchCard,
    backgroundImageConfig,
) {
    if (fields.backgroundImage) {
        const imgAttributes = {
            loading: merchCard.loading ?? 'lazy',
            src: fields.backgroundImage,
        };
        if (fields.backgroundImageAltText) {
            imgAttributes.alt = fields.backgroundImageAltText;
        } else {
            imgAttributes.role = 'none';
        }
        if (!backgroundImageConfig) return;
        if (backgroundImageConfig?.attribute) {
            merchCard.setAttribute(
                backgroundImageConfig.attribute,
                fields.backgroundImage,
            );
            return;
        }
        merchCard.append(
            createTag(
                backgroundImageConfig.tag,
                { slot: backgroundImageConfig.slot },
                createTag('img', imgAttributes),
            ),
        );
    }
}

/**
 * Process mnemonic elements in HTML content
 * Ensures mas-mnemonic elements have proper structure
 */
function processMnemonicElements(htmlContent) {
    if (!htmlContent || typeof htmlContent !== 'string') return htmlContent;

    // This function ensures mas-mnemonic elements are properly formed
    // The actual parsing happens when the HTML is added to the DOM
    // and the mas-mnemonic web component initializes

    // Import mas-mnemonic to ensure it's loaded when mnemonics are used
    if (htmlContent.includes('<mas-mnemonic')) {
        import('./mas-mnemonic.js').catch(console.error);
    }

    return htmlContent;
}

export function processPrices(fields, merchCard, mapping) {
    if (fields.prices) {
        fields.prices = processMnemonicElements(fields.prices);
    }
    appendSlot('prices', fields, merchCard, mapping);
}

function transformLinkToButton(linkElement, merchCard, aemFragmentMapping) {
    const isCheckoutLink =
        linkElement.hasAttribute('data-wcs-osi') &&
        Boolean(linkElement.getAttribute('data-wcs-osi'));
    const originalClassName = linkElement.className || '';
    const checkoutLinkStyle =
        CHECKOUT_STYLE_PATTERN.exec(originalClassName)?.[0] ?? 'accent';
    const isAccent = checkoutLinkStyle.includes('accent');
    const isPrimary = checkoutLinkStyle.includes('primary');
    const isSecondary = checkoutLinkStyle.includes('secondary');
    const isOutline = checkoutLinkStyle.includes('-outline');
    const isLinkStyle = checkoutLinkStyle.includes('-link');

    linkElement.classList.remove('accent', 'primary', 'secondary');

    let newButtonElement;

    if (merchCard.consonant) {
        newButtonElement = createConsonantButton(
            linkElement,
            isAccent,
            isCheckoutLink,
            isLinkStyle,
            isPrimary,
            isSecondary,
            aemFragmentMapping?.ctas?.size,
        );
    } else if (isLinkStyle) {
        newButtonElement = linkElement;
    } else {
        let variant;
        if (isAccent) {
            variant = 'accent';
        } else if (isPrimary) {
            variant = 'primary';
        } else if (isSecondary) {
            variant = 'secondary';
        }

        newButtonElement =
            merchCard.spectrum === 'swc'
                ? createSpectrumSwcButton(
                      linkElement,
                      aemFragmentMapping,
                      isOutline,
                      variant,
                      isCheckoutLink,
                  )
                : createSpectrumCssButton(
                      linkElement,
                      aemFragmentMapping,
                      isOutline,
                      variant,
                      isCheckoutLink,
                  );
    }
    return newButtonElement;
}

function processDescriptionLinks(merchCard, aemFragmentMapping) {
    const { slot } = aemFragmentMapping?.description;
    const links = merchCard.querySelectorAll(
        `[slot="${slot}"] a[data-wcs-osi]`,
    );
    if (!links.length) return;
    links.forEach((link) => {
        const checkoutLink = transformLinkToButton(
            link,
            merchCard,
            aemFragmentMapping,
        );
        link.replaceWith(checkoutLink);
    });
}

export function processDescription(fields, merchCard, mapping) {
    if (fields.description) {
        fields.description = processMnemonicElements(fields.description);
    }
    if (fields.promoText) {
        fields.promoText = processMnemonicElements(fields.promoText);
    }
    if (fields.shortDescription) {
        fields.shortDescription = processMnemonicElements(
            fields.shortDescription,
        );
    }

    appendSlot('promoText', fields, merchCard, mapping);
    appendSlot('description', fields, merchCard, mapping);
    appendSlot('shortDescription', fields, merchCard, mapping);

    if (fields.shortDescription) {
        merchCard.setAttribute('action-menu', 'true');
        if (!fields.actionMenuLabel) {
            merchCard.setAttribute('action-menu-label', 'More options');
        }
    }

    processDescriptionLinks(merchCard, mapping);
    appendSlot('callout', fields, merchCard, mapping);
    appendSlot('quantitySelect', fields, merchCard, mapping);
    appendSlot('whatsIncluded', fields, merchCard, mapping);
}

export function processAddon(fields, merchCard, mapping) {
    if (!mapping.addon) return;
    const addonField = fields.addon?.replace(/[{}]/g, '');
    if (!addonField) return;
    if (/disabled/.test(addonField)) return;
    const addon = createTag('merch-addon', { slot: 'addon' }, addonField);
    [...addon.querySelectorAll(SELECTOR_MAS_INLINE_PRICE)].forEach((span) => {
        const parent = span.parentElement;
        if (parent?.nodeName !== 'P') return;
        parent.setAttribute('data-plan-type', '');
    });
    merchCard.append(addon);
}

